CREATE OR REPLACE FUNCTION public.chess_new(p_opponent uuid, p_white boolean)
 RETURNS chat_games
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare g chat_games;
begin
  if auth.uid() is null or public.my_join_time() is null then raise exception 'not a member'; end if;
  if p_opponent = auth.uid() or not exists (select 1 from chat_members where user_id = p_opponent) then raise exception 'bad opponent'; end if;
  insert into chat_games (white, black, created_by)
  values (case when p_white then auth.uid() else p_opponent end, case when p_white then p_opponent else auth.uid() end, auth.uid())
  returning * into g;
  return g;
end $function$

CREATE OR REPLACE FUNCTION public.chess_resign(p_game bigint)
 RETURNS chat_games
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare g chat_games;
begin
  select * into g from chat_games where id = p_game for update;
  if not found or g.status <> 'active' then raise exception 'game over'; end if;
  if auth.uid() not in (g.white, g.black) then raise exception 'not a player'; end if;
  update chat_games set status = 'resigned', winner = case when auth.uid() = g.white then g.black else g.white end, updated_at = now()
  where id = p_game returning * into g;
  return g;
end $function$

CREATE OR REPLACE FUNCTION public.join_chat(code text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare ok boolean; inv chat_invites%rowtype; c text := lower(trim(code));
begin
  if auth.uid() is null then return false; end if;
  if exists (select 1 from chat_bans where user_id = auth.uid()) then perform pg_sleep(1); return false; end if;
  if exists (select 1 from chat_members where user_id = auth.uid()) then return true; end if;
  select invite_hash = crypt(c, invite_hash) into ok from chat_settings where id = 1;
  if coalesce(ok, false) then
    insert into chat_members (user_id) values (auth.uid()) on conflict do nothing;
    return true;
  end if;
  select * into inv from chat_invites
    where code_hash = encode(digest(c, 'sha256'), 'hex') and not revoked and uses < max_uses and (expires_at is null or expires_at > now())
    for update;
  if not found then perform pg_sleep(1); return false; end if;
  insert into chat_members (user_id, invited_by, invite_id) values (auth.uid(), inv.created_by, inv.id) on conflict do nothing;
  update chat_invites set uses = uses + 1 where id = inv.id;
  return true;
end
$function$

CREATE OR REPLACE FUNCTION public.create_invite(p_note text DEFAULT NULL::text, p_max_uses integer DEFAULT 1, p_days integer DEFAULT 7)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  w text[] := array['whisker','comet','nebula','tabby','rocket','purr','saturn','mitten','pounce','meteor','galaxy','paw','orbit','lunar','quasar','kitten','nova','tuna','yarn','pulsar','cosmic','meow','ginger','calico'];
  b bytea := gen_random_bytes(4);
  code text;
begin
  if my_join_time() is null then raise exception 'not a member'; end if;
  code := w[1 + get_byte(b, 0) % 24] || '-' || w[1 + get_byte(b, 1) % 24] || '-' || lpad(((get_byte(b, 2) * 256 + get_byte(b, 3)) % 10000)::text, 4, '0');
  insert into chat_invites (code_hash, code_hint, note, max_uses, expires_at)
  values (
    encode(digest(code, 'sha256'), 'hex'), right(code, 4), nullif(trim(p_note), ''),
    greatest(1, least(coalesce(p_max_uses, 1), 50)),
    case when p_days is null or p_days <= 0 then null else now() + make_interval(days => least(p_days, 365)) end
  );
  return code;
end
$function$

CREATE OR REPLACE FUNCTION public.remove_member(p_user uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_owner() or p_user = auth.uid() then return false; end if;
  delete from chat_members where user_id = p_user;
  insert into chat_bans (user_id, banned_by) values (p_user, auth.uid()) on conflict do nothing;
  return true;
end
$function$

CREATE OR REPLACE FUNCTION public.merge_members(p_keep uuid, p_drop uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_owner() or p_keep = p_drop then return false; end if;
  if not exists (select 1 from chat_members where user_id = p_keep) then return false; end if;
  update chat_messages set sender = p_keep where sender = p_drop;
  insert into chat_reactions (message_id, user_id, emoji, created_at)
    select message_id, p_keep, emoji, created_at from chat_reactions where user_id = p_drop on conflict do nothing;
  delete from chat_reactions where user_id = p_drop;
  update chat_members k set joined_at = least(k.joined_at, d.joined_at) from chat_members d where k.user_id = p_keep and d.user_id = p_drop;
  update chat_invites set created_by = p_keep where created_by = p_drop;
  update chat_members set invited_by = p_keep where invited_by = p_drop;
  if exists (select 1 from chat_names where id = p_keep) then delete from chat_names where id = p_drop;
  else update chat_names set id = p_keep where id = p_drop; end if;
  delete from chat_members where user_id = p_drop;
  return true;
end
$function$

CREATE OR REPLACE FUNCTION public.chess_move(p_game bigint, p_move text, p_ply integer, p_status text)
 RETURNS chat_games
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare g chat_games; n int;
begin
  select * into g from chat_games where id = p_game for update;
  if not found or g.status <> 'active' then raise exception 'game over'; end if;
  n := coalesce(array_length(g.moves, 1), 0);
  if n <> p_ply then raise exception 'out of sync'; end if;
  if (n % 2 = 0 and g.white <> auth.uid()) or (n % 2 = 1 and g.black <> auth.uid()) then raise exception 'not your turn'; end if;
  if p_move !~ '^[A-Za-z0-9+#=-]{2,8}$' then raise exception 'bad move'; end if;
  if p_status not in ('active', 'checkmate', 'stalemate', 'draw') then raise exception 'bad status'; end if;
  update chat_games set moves = moves || p_move, status = p_status,
    winner = case when p_status = 'checkmate' then auth.uid() else null end, updated_at = now()
  where id = p_game returning * into g;
  return g;
end $function$
